local UIActivityMainQuestionnaireNode = Class('UIActivityMainQuestionnaireNode')

function UIActivityMainQuestionnaireNode:__init()
    self._data = {}
    self._surveyDojo = nil        --问卷内容
end

function UIActivityMainQuestionnaireNode:__delete()
    self._data = nil
    self._surveyDojo = nil        --问卷内容
end

function UIActivityMainQuestionnaireNode:Awake()
    SetButtonAction(self.BtnLeavefor, Bind(self, self.OnClick))
end

function UIActivityMainQuestionnaireNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    self:FillSelf()
    self:RefreshContent()
    self:RefreshCurrencyBarInfo()
end

function UIActivityMainQuestionnaireNode:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods()
end

function UIActivityMainQuestionnaireNode:FillSelf()
    local startTime = self._data.startTime
    local closeTime = self._data.closeTime
    CfUtils.FillText(self.Text, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.TextTitle, self._data.name)
end

--刷新内容
function UIActivityMainQuestionnaireNode:RefreshContent()
    GameUtils.Request(Interfaces.ActivitySurvey, {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
    
        local jsonData = response.data
        local dojo = ActivitySurveyDojo.New()
        dojo:Fill(jsonData)
        self._surveyDojo = dojo

        self:FillSurvey()
    end)
end

--绘制问卷
function UIActivityMainQuestionnaireNode:FillSurvey()
    if not self._surveyDojo then
        return
    end

    CfUtils.FillText(self.TextLeavefor, self._surveyDojo.button)
    self:FillContent(self._data.detail)
    self:FillRewards(self._surveyDojo.rewards)
end

local function find(str, substr, callback, init)
    init = init or 1
    local first, last = str:find(substr, init)
    if first then
        callback(str, first, last, init)
        return find(str, substr, callback, last+1)
    end
 end

--绘制文本
function UIActivityMainQuestionnaireNode:FillContent(content)
    content = checkString(content)
    --content = "12{Image=https://img.fantanggame.com/cat-phone/0fd3a1d6eed0bd8d9435e90dde48018b.png}4ed{Image=1.png}333"
    --local imgs = Regex.Matches(content, "<Image=(.+)>") 
    --local texts = Regex.Split(content, "({.*?})") 

    local texts = {}
    local t = {}
    find(content, "%b{}", function(str, first, last)
        table.insert(t, first)
        table.insert(t, last)
    end)

    if table.count(t) > 0 then
        if t[1] > 1 then
            table.insert(t, 1, 1)
        end
        if t[#t] < string.len(content) then
            table.insert(t, string.len(content)) 
        end
    
        for i = 1, #t - 1 do
            table.insert(texts, string.sub(content, t[i] + 1, t[i + 1] - 1))
        end
    else
        table.insert(texts, content)
    end

    if isNull(texts) then
        return
    end
    
    for i = 1, self.Content.childCount do
        KTool.SetActive(self.Content:GetChild(i - 1), false)
    end
    local height = 0
    local len = table.count(texts)
    for i = 1, len do
        local str = texts[i]
        local isImg = self:IsImage(str)
        local go = self:GetTextOrImageNode(i, isImg)
        if go then
            KTool.SetActive(go, true)
            --是图片
            if isImg then 
                local spls = CfUtils.Split(str, '=')
                if table.count(spls) > 1 then
                    CfUtils.FillWebImage(go, string.sub(spls[2], 1, str.len(spls[2]) - 1))
                end
            else
                CfUtils.FillText(go, texts[i])
            end

            local pos = go.transform.localPosition
            go.transform.localPosition = Vector3(pos.x, height, pos.z)

            local goRt = go.transform:GetComponent(typeof(RectTransform))
            if isImg then 
                height = height - goRt.rect.height
            else
                height = height - CS.UnityEngine.UI.LayoutUtility.GetPreferredHeight(goRt)
            end
            height = height - 5
        end
    end
    local rt = self.Content.transform:GetComponent(typeof(RectTransform))
    rt.sizeDelta = Vector2(rt.sizeDelta.x, math.abs(height))
end

--奖励
function UIActivityMainQuestionnaireNode:FillRewards(rewards)
    if not rewards then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsListNode)
    if not scr then
        return
    end
    scr:FreshBaseUI(rewards, false)
end

function UIActivityMainQuestionnaireNode:GetTextOrImageNode(ind, isImage)
    ind = checkNumber(ind)
    local name = (isImage and "img" or "text")
    local go = self.Content.transform:Find(name..ind)
    if not go then
        go = CfUtils.InstantiateGo((isImage and self.ImgPhoto or self.TextDescribe), self.Content)
        go.name = name..ind
    end
    return go
end

function UIActivityMainQuestionnaireNode:IsImage(str)
    str = checkString(str)
    return string.find(str, "Image=")
end

function UIActivityMainQuestionnaireNode:OnClick()
    if not self._surveyDojo then
        GameUtils.Toast(localize("问卷不存在"))
        return
    elseif self._data.closeTime <= os.time() then
        GameUtils.Toast(localize("该问卷已过期"))
        return
    elseif checkNumber(self._surveyDojo.submitted) == 1 then
        GameUtils.Toast(localize("该问卷已完成, 请前往邮箱领取奖励"))
        return
    end
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._data.id)))
    CfUtils.OpenURL(self._surveyDojo.url);
end

function UIActivityMainQuestionnaireNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityMainQuestionnaireNode
